"""Self-contained local review interface; no CDN, telemetry or external assets."""
HTML=r'''<!doctype html><html lang="es"><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Sakura · Matching HD</title>
<style>
:root{color-scheme:light;font:16px system-ui,sans-serif;color:#4c2938;background:#f7eee4;--pink:#88314f;--line:#e5c8cd}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 10% 0%,#f5d8df,transparent 45%),#f7eee4}
header{padding:28px 4vw 18px;display:flex;gap:20px;align-items:center;justify-content:space-between;flex-wrap:wrap}
h1{font-size:27px;margin:0 0 6px}h2{font-size:18px;margin:0 0 12px}p{line-height:1.5;margin:6px 0;color:#795b65}
button,select,input{font:inherit;border:1px solid var(--line);border-radius:18px;padding:10px 16px;background:#fffaf3;color:inherit}
button{cursor:pointer}button:hover{border-color:var(--pink);background:#fae5e8}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #b97b31;outline-offset:3px}
.primary{background:var(--pink);color:white;border-color:var(--pink)}.primary:hover{background:#a24967}.muted{font-size:14px;color:#795b65}
main{padding:0 4vw 30px;max-width:1600px;margin:auto}.toolbar,.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.toolbar{padding:14px 0 20px}.card{background:#fffbf4;border:1px solid #ecd8d5;border-radius:28px;padding:22px;box-shadow:0 5px #6d35480b}
.columns{display:grid;grid-template-columns:minmax(180px,250px) 1fr;gap:22px}.list{max-height:72vh;overflow:auto;display:grid;gap:8px;align-content:start}
.list button{text-align:left;display:flex;justify-content:space-between;gap:10px;border-radius:14px}.list button.current{background:#f6dfe4;border:2px solid var(--pink)}
.previews{display:grid;grid-template-columns:1fr 1fr;gap:20px}.picture{min-height:350px;display:grid;place-items:center;overflow:auto;padding:15px;background-color:#f0e7dc;background-image:linear-gradient(45deg,#e5d9cc 25%,transparent 25%),linear-gradient(-45deg,#e5d9cc 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#e5d9cc 75%),linear-gradient(-45deg,transparent 75%,#e5d9cc 75%);background-size:20px 20px;background-position:0 0,0 10px,10px -10px,-10px 0;border-radius:18px}
canvas,img{image-rendering:pixelated;max-width:none}.candidates{display:grid;grid-template-columns:repeat(5,minmax(85px,1fr));gap:10px;margin:18px 0}.candidate{padding:12px 8px;display:grid;justify-items:center;gap:8px}
.candidate.chosen{border:2px solid var(--pink);background:#f8e3e7}.candidate img{width:80px;height:160px}.badge{font-size:12px;padding:4px 9px;border-radius:14px;background:#f0e2cf;white-space:nowrap}.badge.auto{background:#e5eddc}.badge.accepted{background:#cfe9d7}.badge.rejected{background:#efdddd}
.controls{margin-top:15px;display:flex;gap:20px;align-items:center;flex-wrap:wrap}.controls input[type=number]{width:85px}#message{padding:13px 4vw;min-height:48px;color:#537b4f}.error{color:#a32940!important}.disabled{opacity:.6;pointer-events:none}
@media(max-width:950px){.columns{grid-template-columns:1fr}.list{max-height:155px;grid-template-columns:repeat(auto-fit,minmax(150px,1fr))}.previews{grid-template-columns:1fr}.candidates{grid-template-columns:repeat(auto-fit,minmax(90px,1fr))}header{padding:20px}.picture{min-height:300px}}
</style>
<header><div><h1>🌸 Sakura · Matching HD</h1><p>Empareja, ajusta y prepara tus retratos para SaturnTaisenFirst.</p></div><button class="primary" id="export">Exportar al recomp</button></header>
<main><div class="toolbar"><span id="summary"></span><label>Mostrar <select id="filter"><option value="pending">Por revisar</option><option value="all">Todos</option><option value="auto">Preseleccionados</option><option value="accepted">Aceptados</option></select></label><button id="previous">← Anterior</button><button id="next">Siguiente →</button></div>
<div class="columns"><nav class="list card" id="list" aria-label="Retratos"></nav><section class="card">
<div class="actions"><h2 id="title"></h2><span id="status" class="badge"></span></div><p class="muted">Hoja de retrato: rostro y piezas de expresión. Los casos parecidos se dejan para revisión.</p>
<div class="actions"><button class="primary" id="accept">Aceptar y siguiente</button><button id="reject">Omitir</button><button id="pending">Dejar para revisar</button></div><div class="previews" style="margin-top:16px"><div><h2>Saturn original</h2><div class="picture"><canvas id="native"></canvas></div></div><div><h2>PC adaptado a la rejilla Saturn</h2><div class="picture"><canvas id="prepared"></canvas></div></div></div>
<div class="controls"><label>Ajuste X <input id="dx" type="number" min="-4" max="4" step="1" value="0"></label><label>Ajuste Y <input id="dy" type="number" min="-4" max="4" step="1" value="0"></label><button id="adjust">Aplicar ajuste</button><label><input type="checkbox" id="overlay"> Solapar original</label></div>
<div id="candidates" class="candidates"></div>
<p class="muted">← → Retrato · 1–5 Candidato · Enter Aceptar. Los cambios se guardan en tu proyecto local.</p>
<p class="muted">La salida conserva coordenadas nativas y variantes de densidad 1×/2× para presentarlas con escala entera.</p>
</section></div></main><div id="message" role="status" aria-live="polite"></div>
<script>
const TOKEN=__TOKEN__;let project,current=0,revision=0,nativeImage,preparedImage;
const $=id=>document.getElementById(id),labels={auto:'Preseleccionado',accepted:'Aceptado',pending:'Revisar',rejected:'Omitido'};
const message=(text,error=false)=>{$('message').textContent=text;$('message').className=error?'error':''};
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Matcher-Token':TOKEN}:{},body:body?JSON.stringify(body):undefined});const value=await r.json();if(!r.ok)throw new Error(value.error||'No se pudo completar');return value}
function visible(){const f=$('filter').value;return project.rows.map((r,i)=>[r,i]).filter(([r])=>f==='all'||r.status===f)}
async function load(keep=false){project=await api('/api/project');if(!project.rows.length){message('No hay recursos en el catálogo.',true);return}const selected=visible();if(!keep&&!selected.some(([,i])=>i===current))current=selected.length?selected[0][1]:0;render()}
function navigation(direction){const options=visible();if(!options.length)return;const pos=options.findIndex(([,i])=>i===current);current=options[pos<0?(direction>0?0:options.length-1):(pos+direction+options.length)%options.length][1];render()}
function paint(){if(!nativeImage||!preparedImage)return;for(const [id,image] of [['native',nativeImage],['prepared',preparedImage]]){const canvas=$(id);const box=canvas.parentElement;const logical=Math.max(2,Math.min(6,Math.floor((box.clientWidth-30)/40/2)*2));canvas.width=40*logical;canvas.height=80*logical;const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);if(id==='prepared'&&$('overlay').checked){ctx.globalAlpha=.45;ctx.drawImage(nativeImage,0,0,canvas.width,canvas.height);ctx.globalAlpha=1}}}
function render(){const row=project.rows[current];$('summary').textContent=project.rows.length+' retratos · '+project.rows.filter(r=>r.status==='auto').length+' preseleccionados · '+project.rows.filter(r=>r.status==='accepted').length+' aceptados';$('title').textContent='Saturn 0x'+row.id+' → PC '+row.selected;$('status').textContent=labels[row.status];$('status').className='badge '+row.status;$('dx').value=row.dx;$('dy').value=row.dy;
 $('list').replaceChildren();for(const [entry,index]of visible()){const button=document.createElement('button');button.className=index===current?'current':'';const name=document.createElement('span'),state=document.createElement('span');name.textContent='0x'+entry.id;state.textContent=labels[entry.status];state.className='badge '+entry.status;button.append(name,state);button.onclick=()=>{current=index;render()};$('list').append(button)}
 $('candidates').replaceChildren();row.candidates.forEach((candidate,n)=>{const button=document.createElement('button');button.className='candidate'+(candidate.index===row.selected?' chosen':'');const picture=document.createElement('img');picture.src='/image/pc/'+candidate.index;picture.alt='Candidato PC '+candidate.index;const title=document.createElement('span');title.textContent=(n+1)+'. PC '+candidate.index;const detail=document.createElement('small');detail.textContent=candidate.error<.04?'Muy cercano':candidate.error<.07?'Cercano':'Comparar';button.append(picture,title,detail);button.onclick=()=>choose(candidate.index);$('candidates').append(button)});
 const version=++revision;nativeImage=preparedImage=null;const n=new Image(),p=new Image();n.onload=()=>{if(version===revision){nativeImage=n;paint()}};p.onload=()=>{if(version===revision){preparedImage=p;paint()}};n.src='/image/native/'+row.id;p.src='/image/prepared/'+row.id+'?v='+version;
}
async function update(extra,next=false){try{const row=project.rows[current];await api('/api/choose',{id:row.id,selected:row.selected,status:row.status,dx:row.dx,dy:row.dy,...extra});message('Guardado en tu proyecto.');await load(true);if(next)navigation(1)}catch(e){message(e.message,true)}}
function choose(index){update({selected:index,status:'pending'})}
$('filter').onchange=()=>load().catch(e=>message(e.message,true));$('previous').onclick=()=>navigation(-1);$('next').onclick=()=>navigation(1);$('accept').onclick=()=>update({status:'accepted'},true);$('reject').onclick=()=>update({status:'rejected'},true);$('pending').onclick=()=>update({status:'pending'});$('adjust').onclick=()=>update({dx:Number($('dx').value),dy:Number($('dy').value),status:'pending'});$('overlay').onchange=paint;window.onresize=paint;
$('export').onclick=async()=>{try{$('export').disabled=true;message('Preparando variantes y manifiesto…');const r=await api('/api/export',{});message(r.portraits+' retratos exportados. Reinicia el juego para cargar el pack.')}catch(e){message(e.message,true)}finally{$('export').disabled=false}};
document.onkeydown=e=>{if(['INPUT','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='ArrowLeft'){e.preventDefault();navigation(-1)}if(e.key==='ArrowRight'){e.preventDefault();navigation(1)}if(e.key==='Enter'){e.preventDefault();$('accept').click()}if(/^[1-5]$/.test(e.key)){const c=project.rows[current].candidates[Number(e.key)-1];if(c)choose(c.index)}};
load().catch(e=>message(e.message,true));
</script></html>'''
